update public.study_sets set units = units || (
  select coalesce(jsonb_agg(x), '[]'::jsonb) from jsonb_array_elements('[{"u": 8, "name": "Colours"},{"u": 9, "name": "Time"},{"u": 10, "name": "Money & work"},{"u": 11, "name": "Love & people"},{"u": 12, "name": "Tricky situations"},{"u": 13, "name": "Everyday life"}]'::jsonb) x
   where not exists (select 1 from jsonb_array_elements(units) o where (o->>'u')::int = (x->>'u')::int))
 where id = '00000000-0000-4000-8000-00000000d10e';

